class Solution {
    public:int maxScore(vector<int>& a) {
        int n=a.size();
        long long total=accumulate(a.begin(),a.end(),0LL);
        if(n<=2)return 0;
        if(n%2) {
            return (int)(total-*min_element(a.begin(),a.end()));
        }
        int best=INT_MAX;
        for(int i=1; i<n; i++)best=min(best,a[i-1]+a[i]);
        return (int)(total-best);
    }
}
